import json,pathlib,hashlib,shutil
root=pathlib.Path(__file__).resolve().parents[2];out=root/'docs/audits/2026-09-25-trend-research';read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
labels={'':'Gần đây: 26/07–24/09/2026','history_2023':'01–06/2023','history_2024':'07–12/2024','train':'02–06/2025','validation':'07–09/2025'}
